                }
            }
        }
        return 2 * maxMatching(adj);
    }

    static int maxMatching(boolean[][] g) {
        int n1 = g.length;
        int n2 = n1 == 0 ? 0 : g[0].length;
        int[] match = new int[n2];
        Arrays.fill(match, -1);
        int count = 0;
        for (int u = 0; u < n1; u++) {
            boolean[] visited = new boolean[n1];
            if (dfs(u, g, match, visited))
