#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
    Point(int x, int y) : x(x), y(y) {}
};

static istream& in = cin;
static ostream& out = cout;

int bruteforce(int n, int m) {
    vector<Point> evenPoints, oddPoints;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if ((i + j) % 2 == 0) {
                evenPoints.emplace_back(i, j);
            } else {
                oddPoints.emplace_back(i, j);
            }
        }
    }
    int en = (int)evenPoints.size();
    int on = (int)oddPoints.size();
    vector<vector<bool>> adj(en, vector<bool>(on, false));
    for (int i = 0; i < en; i++) {
        for (int j = 0; j < on; j++) {
            int dist = abs(evenPoints[i].x - oddPoints[j].x) + abs(evenPoints[i].y - oddPoints[j].y);
            if (dist == 3) {
                adj[i][j] = true;
            }
        }
    }
    return 2 * maxMatching(adj);
}

int maxMatching(const vector<vector<bool>>& g) {
    int n1 = (int)g.size();
    int n2 = n1 > 0 ? (int)g[0].size() : 0;
    vector<int> match(n2, -1);
    int result = 0;
    for (int u = 0; u < n1; u++) {
        vector<bool> visited(n1, false);
        if (dfs(u, g, match, visited))
            result++;
    }
    return result;
}

bool dfs(int u, const vector<vector<bool>>& g, vector<int>& match, vector<bool>& vis) {
    vis[u] = true;
    for (int v = 0; v < (int)match.size(); v++) {
        if (g[u][v] && (match[v] == -1 || (!vis[match[v]] && dfs(match[v], g, match, vis)))) {
            match[v] = u;
            return true;
        }
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    in >> n >> m;
    if (n > m) {
        swap(n, m);
    }
    if (n == 1) {
        m--;
        int pattern[] = {0, 0, 0, 2, 4, 6};
        long long result = (m / 6) * 6 + pattern[m % 6];
        out << result << "\n";
    } else if (n == 2) {
        if (m < 20) {
            out << bruteforce(n, m) << "\n";
        } else {
            out << (long long)n * m << "\n";
        }
    } else if (n == 3) {
        if (m < 20) {
            out << bruteforce(n, m) << "\n";
        } else {
            long long res = (long long)n * m;
            if (res % 2 != 0) res--;
            out << res << "\n";
        }
    } else {
        long long total = (long long)n * m;
        if (total % 2 != 0) total--;
        out << total << "\n";
    }
    return 0;
}
